// Front wall collision (positive Z)
if (p->position.z > boxWidth - h) {
    p->position.z = boxWidth - h - (p->position.z - (boxWidth - h)) + h + BOX_COLLISION_OFFSET;
    p->velocity.z = -p->velocity.z * elasticity;
}

// Back wall collision (negative Z)
if (p->position.z < -boxWidth + h) {
    p->position.z = -boxWidth + h - (p->position.z - (-boxWidth + h)) - h - BOX_COLLISION_OFFSET;
    p->velocity.z = -p->velocity.z * elasticity;
}

